import java.util.Scanner;

public class P181A {

    public static void main(String[]args){

        Scanner scn = new Scanner(System.in);
        int r  = scn.nextInt();
        int c = scn.nextInt();

        // running XOR of star rows/cols: pairs cancel, the odd one is left
        int ansRow = 0;
        int ansCol = 0;

        // each row of the grid is one String like ".*."
        for(int i = 0; i < r; i++){

            String line = scn.next();

            for(int j = 0; j < c; j++){

                if(line.charAt(j) == '*'){

                    ansRow ^= i + 1;   // +1 because Codeforces counts from 1
                    ansCol ^= j + 1;
                }
            }
        }

        System.out.println(ansRow + " " + ansCol);
    }
}
